#include "ImageEngine.h"
#include <cassert>
int main(){picsay::Image a; a.width=2;a.height=1;a.rgba={255,0,0,255,0,255,0,128};assert(picsay::invert(a));assert(a.rgba[0]==0&&a.rgba[1]==255);assert(picsay::grayscale(a));picsay::Image b;assert(picsay::rotate90(a,1,b));assert(b.width==1&&b.height==2);picsay::Image c;assert(picsay::crop(a,0,0,1,1,c));assert(c.valid());assert(picsay::pixelize(a,2));assert(picsay::boxBlur(a,1));assert(picsay::sharpen(a,1));assert(picsay::warpBulge(a,0,0,2,.2f));assert(picsay::blend(a,c,0,0,.5f));return 0;}